<template><div class="ledger-page"><section class="card-compact"><h2>操作日志</h2><p>记录功能启用后的操作。关键付款、工资条动作与业务记录同事务保存；历史记录不会凭空补造。账户和密钥等内容已脱敏。</p><div class="ledger-tools"><el-input v-model="filters.actor_id" placeholder="操作人账号编号" style="width:160px"/><el-input v-model="filters.action" placeholder="操作／接口" style="width:230px"/><el-input v-model="filters.resource" placeholder="记录对象" style="width:180px"/><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD"/><el-button @click="page=1;load()">查询</el-button></div><p class="ledger-error" role="alert">{{error}}</p></section><section class="card-compact"><el-table :data="items" v-loading="loading" @row-click="row=>{selected=row;dialog=true}"><el-table-column label="时间（北京时间）" min-width="190"><template #default="{row}">{{new Date(row.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}}</template></el-table-column><el-table-column prop="actor_name" label="操作人"/><el-table-column prop="channel" label="终端" width="80"/><el-table-column prop="action" label="操作" min-width="220"/><el-table-column prop="resource" label="对象" min-width="180"/></el-table><el-pagination :current-page="page" :page-size="50" :total="total" layout="total,prev,pager,next" @current-change="v=>{page=v;load()}"/></section><NotificationDialog v-model="dialog" title="操作变更详情"><template v-if="selected"><p>{{selected.actor_name}} · {{selected.action}}</p><h4>变更前</h4><pre>{{format(selected.before_json)}}</pre><h4>变更后／提交内容</h4><pre>{{format(selected.after_json)}}</pre></template></NotificationDialog></div></template>
<script setup>
import {onMounted,ref} from 'vue'
import {businessLedgerApi as api} from '@/api'
import NotificationDialog from '@/components/NotificationDialog.vue'
import '@/styles/business-ledger.css'
const filters=ref({actor_id:'',action:'',resource:''}),dates=ref([]),items=ref([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(''),selected=ref(null),dialog=ref(false)
const format=s=>{try{return JSON.stringify(JSON.parse(s),null,2)}catch{return s}}
async function load(){loading.value=true;error.value='';try{const r=await api.audit({...filters.value,from:dates.value?.[0],to:dates.value?.[1],page:page.value});items.value=r.items;total.value=r.total}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(load)
</script><style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:40vh;overflow:auto}</style>
